<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { get,post } from '../api';import RiskTag from '../components/RiskTag.vue';const route=useRoute(),router=useRouter(),p=ref<any>(),quick=ref(false),saving=ref(false),note=ref('');const serviceLabels:Record<string,string>={BIDDING:'招标代理',COST:'造价/预结算',SUPERVISION:'监理',OTHER:'其他'};const money=(n:number)=>`¥${Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:2})}`;const next=computed(()=>p.value?.milestones.filter((m:any)=>!m.actualDate).sort((a:any,b:any)=>a.plannedDate.localeCompare(b.plannedDate))[0]);const service=(x:any)=>serviceLabels[String(x)]||'其他';async function load(){p.value=await get(`/projects/${route.params.id}`)}onMounted(load);async function quickSave(){saving.value=true;try{await post(`/projects/${p.value.id}/quick-update`,{status:p.value.status,services:p.value.services,nextMilestone:next.value?{name:next.value.name,plannedDate:next.value.plannedDate,serviceId:next.value.serviceId}:undefined,note:note.value});quick.value=false;await load()}finally{saving.value=false}}</script>
<template><div v-if="!p" class="empty"><p>正在加载项目…</p></div><template v-else><div class="eyebrow">{{p.status==='ACTIVE'?'在办':p.status==='COMPLETED'?'已完成':'已取消'}} · {{p.services.map((s:any)=>service(s.serviceType)).join(' / ')}}</div><div class="detail-hero"><div><h1 class="title" style="margin-top:10px">{{p.name}}</h1><p class="subtitle">{{p.client?.name}} · {{p.owner?.name}}</p><div style="margin-top:16px"><RiskTag v-for="r in p.risks" :key="r.reason" :level="r.level" :text="r.reason"/></div></div><div class="actions" style="margin:0"><RouterLink :to="`/projects/${p.id}/edit`" class="button secondary">编辑项目</RouterLink><button class="button primary" @click="quick=true">快速更新</button></div></div><div class="hero-metrics"><div class="metric"><label>下一关键节点</label><strong>{{next?.name||'暂无'}}</strong><small class="subtitle" style="display:block;margin-top:8px">{{next?.plannedDate||'可在快速更新中添加'}}</small></div><div class="metric"><label>当前应收</label><strong>{{money(p.finance.receivableAmount)}}</strong><small class="subtitle" style="display:block;margin-top:8px">已回款 {{money(p.finance.paymentAmount)}}</small></div></div><div class="detail-grid"><section><h2 class="section-title">服务与成果</h2><div class="list"><div v-for="s in p.services" :key="s.id" class="list-row"><b>{{service(s.serviceType)}}</b><span>{{s.stage}}</span><span class="subtitle">{{s.otherDescription||s.note}}</span></div></div><h2 class="section-title" style="margin-top:32px">时间</h2><div class="list"><div v-for="m in p.milestones" :key="m.id" class="list-row"><span class="eyebrow">{{m.plannedDate}}</span><span>{{m.name}}</span><RiskTag v-if="!m.actualDate&&m.plannedDate<new Date().toISOString().slice(0,10)" level="danger" text="延期"/><span v-else class="subtitle">{{m.actualDate?'已完成':'待完成'}}</span></div></div><h2 v-if="p.issues.length" class="section-title" style="margin-top:32px">管理问题</h2><div v-for="x in p.issues" class="list-row"><span>{{x.title}}</span><span class="subtitle">{{x.responsibleParty}} · {{x.dueDate}}</span><RiskTag :level="x.status==='CLOSED'?'success':'danger'" :text="x.status==='CLOSED'?'已关闭':'处理中'"/></div></section><aside><h2 class="section-title">经营</h2><div class="list"><div class="list-row"><span>合同额</span><b>{{money(p.finance.contractAmount)}}</b></div><div class="list-row"><span>已开票</span><b>{{money(p.finance.invoiceAmount)}}</b></div><div class="list-row"><span>已回款</span><b>{{money(p.finance.paymentAmount)}}</b></div><div class="list-row"><span>应收</span><b>{{money(p.finance.receivableAmount)}}</b></div></div><h2 class="section-title" style="margin-top:32px">文件 {{p.documents.length}}</h2><div class="list"><div v-for="d in p.documents" class="list-row"><span>{{d.originalName}}</span><span class="subtitle">{{d.title}}</span></div><p v-if="!p.documents.length" class="subtitle">暂无文件。文件上传将存储为新版本，不覆盖历史文件。</p></div><h2 class="section-title" style="margin-top:32px">变更记录</h2><div v-for="a in p.audit.slice(0,5)" class="list-row"><span>{{a.action}}</span><span class="subtitle">{{a.at.slice(0,16).replace('T',' ')}}</span></div></aside></div><el-dialog v-model="quick" title="快速更新" width="min(540px,92vw)"><p class="subtitle" style="margin-bottom:20px">保存会刷新管理复核时间，并根据真实日期重新计算风险。</p><div class="field-group"><label>项目状态</label><select v-model="p.status" class="select"><option value="ACTIVE">在办</option><option value="COMPLETED">已完成</option><option value="CANCELLED">已取消</option></select></div><div v-for="s in p.services" class="field-group" style="margin-top:15px"><label>{{service(s.serviceType)}}当前阶段</label><input v-model="s.stage" class="input"/></div><div v-if="next" class="field-group" style="margin-top:15px"><label>下一节点</label><input v-model="next.name" class="input"/><input v-model="next.plannedDate" type="date" class="input"/></div><div class="field-group" style="margin-top:15px"><label>管理备注</label><textarea v-model="note" class="textarea" rows="3"/></div><template #footer><button class="button secondary" @click="quick=false">取消</button><button class="button primary" :disabled="saving" @click="quickSave">{{saving?'保存中…':'保存更新'}}</button></template></el-dialog></template></template>
